const SVG = 'http://www.w3.org/2000/svg';
const smooth = () => document.documentElement.dataset.skin === 'modern';

function smoothIcon(name) {
  const [kind, d] = SMOOTH[name];
  const svg = document.createElementNS(SVG, 'svg');
  svg.setAttribute('class', `ic ic-${name}`);
  svg.setAttribute('viewBox', '0 0 24 24');
  svg.setAttribute('aria-hidden', 'true');
  const path = document.createElementNS(SVG, 'path');
  path.setAttribute('d', d);
  if (kind === 's') {
    path.setAttribute('fill', 'none');
    path.setAttribute('stroke', 'currentColor');
    path.setAttribute('stroke-width', '2');
    path.setAttribute('stroke-linecap', 'round');
    path.setAttribute('stroke-linejoin', 'round');
  } else {
    path.style.fill = kind === 'a' ? 'var(--accent, currentColor)' : 'currentColor';
  }
  svg.append(path);
  return svg;
}

function pixelIcon(name) {
  const lines = rows(name);
  const size = lines.length;
  const svg = document.createElementNS(SVG, 'svg');
  svg.setAttribute('class', 'px');
  svg.setAttribute('viewBox', `0 0 ${size} ${size}`);
  svg.setAttribute('aria-hidden', 'true');
  if (size === 9) { svg.style.width = '9px'; svg.style.height = '9px'; }
  lines.forEach((line, y) => {
    [...line].forEach((ch, x) => {
      const fill = PALETTE[ch];
      if (!fill) return;
      const rect = document.createElementNS(SVG, 'rect');
      rect.setAttribute('x', x);
      rect.setAttribute('y', y);
      rect.setAttribute('width', 1);
      rect.setAttribute('height', 1);
      rect.style.fill = fill;
      svg.append(rect);
    });
  });
  return svg;
}

// Each icon is drawn once per skin and copied after that. A pixel icon is up to a
// hundred squares, and copying is far cheaper than drawing them again.
const drawn = new Map();

export function icon(name) {
  const smoothed = smooth() && SMOOTH[name];
  const key = `${smoothed ? 'smooth' : 'pixel'}:${name}`;
  let svg = drawn.get(key);
  if (!svg) {
    svg = smoothed ? smoothIcon(name) : pixelIcon(name);
    svg.dataset.icon = name;
    drawn.set(key, svg);
  }
  return svg.cloneNode(true);
}

export function setIcon(node, name) {
  node.replaceChildren(icon(name));
}

/** Redraws every icon on the page, for when the skin changes. */
export function refreshIcons() {
  for (const svg of document.querySelectorAll('svg[data-icon]')) svg.replaceWith(icon(svg.dataset.icon));
}
